// function makeWhereValue
// create a where clause for and atrocore query based on an incoming object.
// the object has the format:
// { ("_andx" | "_orx" | "fieldname") : ( array | scalar | object ), ... }
// _andx and _orx are indicators of a logical and/or, where x represent an identifying number (to avoid key name clashes)
// if the key is an and/or condition, an object is expected as the value; 
// if the key is a fieldname, an array or a scalar is expected
// the output is a JSON object (stringified)
function makeWhereValue(valueObj) {
  let condition;
  const valueArray = [];
  for (const [key, value] of Object.entries(valueObj || {})) {
    if (key.startsWith("_and") || key.startsWith("_or")) {
      condition = {
        "type": (key.startsWith("_and") ? "and" : "or"),
        "value": makeWhereValue(value)
      };
    } else {
      condition = {
        "type": (Array.isArray(value) ? "in" : "equals"),
        "attribute": key,
        "value": value
      };
    }
    valueArray.push(condition);
  }
  return valueArray;
}

